<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {useMessage,useToast} from 'wot-design-uni'
import {createUuid} from '../../domain/id'
import {useClosetStore} from '../../stores/closet'
import {savePhoto,checkLocalStorage,refreshUploads,pumpUploads,uploadRows,uploadError,markPhoto,retryPhoto,removePhotos,removePhoto,quickApi,updateSavedResult,type LocalPhoto,type Hint} from '../../services/quickIntake'
import AuthImage from '../AuthImage.vue'
import TargetMarker from './TargetMarker.vue'
import {choosePhotos,errorText,openGarment,wardrobe} from './navigation'
const closet=useClosetStore(),message=useMessage('quick'),toast=useToast('quick'),session=createUuid(),settings=ref(false),markerMode=ref(false),mode=ref('BASE_READY'),saving=ref(false),received=ref(''),error=ref(''),expanded=ref(false),marker=ref<LocalPhoto>(),celebration=ref(false)
const owner=()=>closet.user?.username
const rows=computed(()=>uploadRows.value.filter(r=>r.owner===owner())),visibleRows=computed(()=>expanded.value?rows.value:rows.value.slice(0,6)),localCount=computed(()=>rows.value.filter(r=>r.state!=='SAVED').length),sessionRows=computed(()=>rows.value.filter(r=>r.options.captureSessionId===session)),sessionReady=computed(()=>sessionRows.value.filter(r=>status(r).success).length)
const active=(r:LocalPhoto)=>!!r.result&&['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(r.result.task.status)
function status(r:LocalPhoto):{title:string;detail:string;success?:boolean}{if(r.state==='MARKING')return{title:'选一下这张的主角',detail:'指定目标后上传，其他照片继续处理'};if(r.state==='ERROR')return{title:'上传未完成',detail:r.error||'照片仍在本机，可以重试'};if(r.state==='UPLOADING')return{title:'正在上传照片',detail:'收到保存确认后，会自动制作贴纸'};if(r.state==='PENDING')return{title:'照片已保存在本机',detail:r.error?'连接恢复后自动重试上传':'等待上传，可以继续拍下一件'};const v=r.result;if(!v)return{title:'照片已保存',detail:'正在读取处理状态'};if(v.garment.status==='TRASHED')return{title:'衣物已移入回收站',detail:'可以在衣柜回收站查看'};const sticker=v.garment.imageProcessing?.stickerReady||v.garment.images.some(i=>i.kind==='BASE_STICKER'),base=v.task.steps.find(s=>s.type==='SEGMENT');if(['FAILED','UNKNOWN','NEEDS_REVIEW'].includes(v.task.status))return{title:sticker?'贴纸已保留，后续处理需查看':'照片已保留，处理需查看',detail:v.task.status==='UNKNOWN'?'云端结果待确认，请到衣物详情查看':'可先使用衣物，或在详情中重新处理'};if(v.task.status==='CANCELLED')return{title:'后续处理已取消',detail:'已保存的衣物和图片仍然保留'};if(sticker)return{title:'贴纸已入柜',detail:active(r)?'现在就能查看使用，资料在后台补齐':'整理完成，可以查看或修改衣物信息',success:true};if(base?.status==='SKIPPED')return{title:'原图已入柜',detail:'去背景未完成，资料识别继续进行'};return{title:v.garment.status==='ACTIVE'?'原图已入柜，贴纸制作中':'照片已保存，正在准备贴纸',detail:base?.status==='RUNNING'?'正在去背景、加白边，做好后自动显示':'已排队，无需再次提交'}}
const sessionPercent=computed(()=>sessionRows.value.length?Math.round(sessionRows.value.filter(r=>status(r).success||r.state==='ERROR'||r.state==='SAVED'&&!active(r)).length/sessionRows.value.length*100):0)
const thumbnail=(r:LocalPhoto)=>r.result?.garment.displayUrl||r.result?.garment.sourceUrl||r.filePath||''
const ai=(r:LocalPhoto)=>r.result?.garment.images.some(i=>i.id===r.result?.garment.displayAssetId&&i.aiGenerated)
let timer:ReturnType<typeof setTimeout>|undefined,alive=true,polling=false
async function capture(source:'album'|'camera'){if(saving.value||uploadError.value)return;try{const photos=await choosePhotos(source,source==='camera'?1:9),account=owner();if(!account||!photos.length)return;saving.value=true;received.value='已收到照片，正在保存在本机…';celebration.value=false;let count=0;for(const file of photos){const row=await savePhoto(account,file.tempFilePath,mode.value,session,markerMode.value);if(owner()!==account)return;if(row.state==='MARKING'&&!marker.value)marker.value=row;count++}received.value=marker.value?'照片已收到，请指定这张的主视衣物。':`收到 ${count} 张照片，正在依次上传。可以继续添加。`;error.value='';toast.success(received.value);void pumpUploads(owner)}catch(e){error.value=errorText(e,'照片保存失败，请重试');received.value=''}finally{saving.value=false}}
async function marked(hint?:Hint){if(!marker.value||!owner())return;try{const id=marker.value.id;await markPhoto(id,owner()!,hint);marker.value=rows.value.find(r=>r.state==='MARKING'&&r.id!==id);void pumpUploads(owner)}catch(e){error.value=errorText(e,'目标保存失败，请重试')}}
async function retry(row:LocalPhoto){try{await retryPhoto(row.id,owner()!);await refreshUploads(owner()!);void pumpUploads(owner)}catch(e){error.value=errorText(e)}}
async function remove(row:LocalPhoto){try{await message.confirm({title:'删除这条录入记录？',msg:row.state==='SAVED'?'只删除这条本机记录，衣物仍在衣柜里。':'这张照片还没上传，删除后无法找回。',confirmButtonText:'删除'});await removePhoto(row.id,owner()!);if(marker.value?.id===row.id)marker.value=undefined}catch(e){if(e instanceof Error)error.value=e.message}}
async function manage(finished:boolean){const targets=rows.value.filter(r=>finished?r.state==='SAVED'&&!active(r):r.state!=='UPLOADING');if(!targets.length)return;const lost=targets.filter(r=>r.state!=='SAVED').length;try{await message.confirm({title:finished?`清除 ${targets.length} 条已完成记录？`:`清空 ${targets.length} 条最近录入？`,msg:`只删除本机的录入记录，已入柜的衣物不受影响。${lost?`其中 ${lost} 张照片还没上传，会一起删除且无法找回。`:''}`,confirmButtonText:finished?'清除':'清空'});await removePhotos(targets.map(r=>r.id),owner()!);if(marker.value&&targets.some(r=>r.id===marker.value?.id))marker.value=undefined;expanded.value=false}catch(e){if(e instanceof Error)error.value=e.message}}
async function check(){try{await checkLocalStorage(owner()||'');error.value=''}catch(e){error.value=errorText(e)}}
async function refresh(){if(!alive||polling||!owner())return;polling=true;const account=owner()!;try{await refreshUploads(account);void pumpUploads(owner);const pending=rows.value.filter(r=>r.state==='SAVED'&&active(r));for(let i=0;i<pending.length&&alive;i+=4)await Promise.all(pending.slice(i,i+4).map(async row=>{const view=await quickApi.get(row.id);if(!alive||owner()!==account)return;await updateSavedResult(row.id,account,view);const current=uploadRows.value.find(r=>r.id===row.id);if(current)current.result=view}));if(sessionRows.value.length&&sessionPercent.value===100&&sessionReady.value)celebration.value=true}catch(e){error.value=errorText(e,'暂时无法刷新进度，已保存的照片不受影响，连接恢复后继续。')}finally{polling=false;if(alive)timer=setTimeout(refresh,localCount.value||rows.value.some(active)?1500:4000)}}
onMounted(()=>void refresh());onShow(()=>{alive=true;clearTimeout(timer);void refresh()});onHide(()=>{alive=false;clearTimeout(timer)});onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><view><view class="section"><view class="row"><text class="section-title">拍一件，收一件</text><wd-button type="text" size="small" @click="settings=true">设置</wd-button></view><text class="subtitle">先做好贴纸给你看，资料自动补齐。</text><view class="actions"><wd-button :loading="saving" :disabled="saving||!!uploadError" @click="capture('camera')">{{rows.length?'再拍一件':'拍照'}}</wd-button><wd-button plain :disabled="saving||!!uploadError" @click="capture('album')">从相册选</wd-button></view><text class="hint">相册可多选 · 拍完自动上传 · 不用等上一件</text><text v-if="received" class="subtitle">{{received}}</text><view v-if="sessionRows.length" class="receipt"><text>本次收了 {{sessionRows.length}} 件{{sessionReady?` · ${sessionReady} 件已入柜`:''}}</text><text class="hint">{{localCount?`${localCount} 张仍在本机，请保持小程序打开完成上传。`:sessionPercent===100?'这一轮都处理好了，可以继续拍或去衣柜看看。':'贴纸在后台制作，可以继续拍下一件。'}}</text><wd-progress :percentage="sessionPercent"/></view><view v-else class="receipt"><text>贴纸做好后自动入柜</text><text class="hint">无需逐件确认，可随时修改和换图。</text></view><text v-if="markerMode||mode==='UPLOAD_READY'" class="hint">{{mode==='UPLOAD_READY'?'当前：原图保存即入柜':''}}{{markerMode?' · 每张指定主视衣物':''}}</text></view>
 <view v-if="celebration" class="section"><text class="section-title">这一轮收好了 {{sessionReady}} 件，新成员已就位</text><text class="subtitle">贴纸都做好了，资料会在后台慢慢补齐。</text><view class="actions"><wd-button @click="wardrobe">去衣柜看看</wd-button><wd-button plain @click="celebration=false;capture('camera')">再拍一件</wd-button><wd-button type="text" @click="celebration=false">关闭</wd-button></view></view>
 <wd-notice-bar v-if="error||uploadError" class="notice" :text="error||uploadError" :scrollable="false" wrapable/><wd-button v-if="uploadError" plain @click="check">重新检查本机存储</wd-button>
 <view class="row"><text class="section-title">最近录入</text><text class="hint">{{rows.length}} 条记录</text></view><view class="actions"><wd-button size="small" type="text" @click="manage(true)">清除已完成记录</wd-button><wd-button size="small" type="text" @click="manage(false)">清空最近录入</wd-button></view><wd-status-tip v-if="!rows.length" image="content" tip="拍一件衣物，最近录入会显示在这里"/>
 <view v-for="row in visibleRows" :key="row.id" class="section"><view class="entry"><view class="thumb"><AuthImage :src="thumbnail(row)" :width="240"/></view><view><text>{{status(row).title}}</text><text class="hint">{{status(row).detail}}</text><text class="hint">{{new Date(row.created).toLocaleString('zh-CN')}}</text></view></view><view class="tags"><wd-tag v-if="ai(row)" plain>AI 生成 · 可能含推测细节</wd-tag><wd-tag v-if="row.result?.quality?.needsEnhancement" type="warning">{{row.result.quality.reason}}</wd-tag></view><view class="actions"><wd-button v-if="row.state==='MARKING'" size="small" @click="marker=row">指定主视衣物</wd-button><wd-button v-if="row.state==='ERROR'" size="small" @click="retry(row)">重试上传</wd-button><wd-button v-if="row.result?.garmentId" size="small" @click="openGarment(row.result.garmentId)">查看衣物</wd-button><wd-button v-if="row.state!=='UPLOADING'" type="text" size="small" @click="remove(row)">删除记录</wd-button></view></view><wd-button v-if="rows.length>6" block plain @click="expanded=!expanded">{{expanded?'收起记录':`查看全部 ${rows.length} 条记录`}}</wd-button>
 <wd-popup v-model="settings" position="bottom" closable><view class="sheet"><text class="sheet-title">录入设置</text><wd-radio-group v-model="mode"><wd-radio value="BASE_READY">贴纸做好后自动入柜（推荐）</wd-radio><wd-radio value="UPLOAD_READY">原图保存即入柜</wd-radio></wd-radio-group><view class="row option"><text>每张指定主视衣物</text><wd-switch v-model="markerMode"/></view><text class="hint">照片会先保存在本机，收到服务器保存确认后才清理本机原图。识别与增强在后台独立处理。</text><wd-button block @click="settings=false">完成</wd-button></view></wd-popup>
 <wd-popup :model-value="!!marker" position="bottom" closable @close="marker=undefined"><TargetMarker v-if="marker?.filePath" :src="marker.filePath" @finish="marked" @close="marker=undefined"/></wd-popup><wd-message-box selector="quick"/><wd-toast selector="quick"/>
</view></template>
<style lang="scss" scoped>@import './closet.scss';.receipt{background:$accent-soft;padding:24rpx;border-radius:$radius-md;margin-top:24rpx}.entry{display:flex;align-items:center;gap:24rpx}.thumb{width:160rpx;height:160rpx;flex-shrink:0}.option{margin:36rpx 0}</style>
